import os
from typing import Dict, List, Optional, Any
from google.cloud import documentai

def extract_invoice_fields(file_path: str) -> Dict[str, Any]:
    """
    Extract vendor, date, total, and line items from an invoice using Google Document AI.
    """
    project_id = os.getenv("GOOGLE_CLOUD_PROJECT")
    location = "us"  # Processor location
    processor_id = os.getenv("DOCUMENT_AI_PROCESSOR_ID")

    if not project_id or not processor_id:
        raise ValueError("GOOGLE_CLOUD_PROJECT and DOCUMENT_AI_PROCESSOR_ID environment variables must be set")

    client = documentai.DocumentProcessorServiceClient()
    processor_name = client.processor_path(project_id, location, processor_id)

    with open(file_path, "rb") as f:
        file_content = f.read()

    raw_document = documentai.RawDocument(content=file_content, mime_type="application/pdf")

    request = documentai.ProcessRequest(name=processor_name, raw_document=raw_document)
    result = client.process_document(request=request)
    document = result.document

    extracted = {
        "vendor": None,
        "date": None,
        "total": None,
        "line_items": []
    }

    for entity in document.entities:
        if entity.type_ == "supplier_name":
            extracted["vendor"] = entity.mention_text
        elif entity.type_ == "invoice_date":
            extracted["date"] = entity.mention_text
        elif entity.type_ == "total_amount":
            extracted["total"] = entity.mention_text
        elif entity.type_ == "line_item":
            line_item = {}
            for prop in entity.properties:
                if prop.type_ == "line_item/description":
                    line_item["description"] = prop.mention_text
                elif prop.type_ == "line_item/amount":
                    line_item["amount"] = prop.mention_text
                elif prop.type_ == "line_item/quantity":
                    line_item["quantity"] = prop.mention_text
                elif prop.type_ == "line_item/unit_price":
                    line_item["unit_price"] = prop.mention_text
            if line_item:
                extracted["line_items"].append(line_item)

    return extracted
